param([Parameter(Mandatory=$true)][int]$ProcessId,[Parameter(Mandatory=$true)][string]$DocumentTitle,[Parameter(Mandatory=$true)][string]$MenuText)
$ErrorActionPreference='Stop';$root=Split-Path -Parent $PSScriptRoot;$source=Join-Path $PSScriptRoot 'cubism_bridge';$jdk=Join-Path $root 'temp\jdk17\jdk-17.0.20+8\bin';$classes=Join-Path $root 'temp\cubism-menu-click-agent\classes';$hash=(Get-FileHash (Join-Path $source 'CubismMenuClickAgent.java') -Algorithm SHA256).Hash.Substring(0,12).ToLowerInvariant();$jar=Join-Path $root "temp\cubism-menu-click-agent-$hash.jar";$manifest=Join-Path $root 'temp\cubism-menu-click-manifest.mf';New-Item -ItemType Directory -Force $classes|Out-Null;if(-not(Test-Path $jar)){@"
