"@|Set-Content $manifest -Encoding ascii;& (Join-Path $jdk 'javac.exe') -encoding UTF-8 -d $classes (Join-Path $source 'AttachAgent.java') (Join-Path $source 'CubismMenuClickAgent.java');if($LASTEXITCODE-ne 0){throw 'javac failed'};& (Join-Path $jdk 'jar.exe') cfm $jar $manifest -C $classes .}; & (Join-Path $jdk 'java.exe') --add-modules jdk.attach -cp $classes AttachAgent $ProcessId $jar "$DocumentTitle|$MenuText";if($LASTEXITCODE-ne 0){throw 'attach failed'}
